  @protected
  void sse_encode_core_event(CoreEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case CoreEvent_MessageReceived(message: final message):
        sse_encode_i_32(0, serializer);
        sse_encode_box_autoadd_message(message, serializer);
      case CoreEvent_MessageStatus(
        id: final id,
        peerId: final peerId,
        status: final status,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_String(id, serializer);
        sse_encode_String(peerId, serializer);
        sse_encode_delivery_status(status, serializer);
      case CoreEvent_ContactOnline(peerId: final peerId):
        sse_encode_i_32(2, serializer);
        sse_encode_String(peerId, serializer);
      case CoreEvent_ContactOffline(peerId: final peerId):
        sse_encode_i_32(3, serializer);
        sse_encode_String(peerId, serializer);
      case CoreEvent_ContactRequest(card: final card):
        sse_encode_i_32(4, serializer);
        sse_encode_box_autoadd_contact_card(card, serializer);
      case CoreEvent_Signal(
        peerId: final peerId,
        callId: final callId,
        kind: final kind,
        payload: final payload,
      ):
        sse_encode_i_32(5, serializer);
        sse_encode_String(peerId, serializer);
        sse_encode_String(callId, serializer);
        sse_encode_signal_kind(kind, serializer);
        sse_encode_String(payload, serializer);
      case CoreEvent_NetworkStatus(info: final info):
        sse_encode_i_32(6, serializer);
        sse_encode_box_autoadd_network_info(info, serializer);
      case CoreEvent_KeyChanged(
        peerId: final peerId,
        oldIdentityKey: final oldIdentityKey,
        newIdentityKey: final newIdentityKey,
        oldSafetyNumber: final oldSafetyNumber,
        newSafetyNumber: final newSafetyNumber,
        source: final source,
      ):
        sse_encode_i_32(7, serializer);
        sse_encode_String(peerId, serializer);
        sse_encode_String(oldIdentityKey, serializer);
        sse_encode_String(newIdentityKey, serializer);
        sse_encode_String(oldSafetyNumber, serializer);
        sse_encode_String(newSafetyNumber, serializer);
        sse_encode_key_change_source(source, serializer);
      case CoreEvent_Server(serverId: final serverId, event: final event):
        sse_encode_i_32(8, serializer);
        sse_encode_String(serverId, serializer);
        sse_encode_box_autoadd_server_event(event, serializer);
    }
  }

